//! Integration tests of `Library::plan_tidy` on the tree generated by `tests/tools/mktidy.py` (FQ1), compared unit
//! by unit with its manifest, plus the cases the generator does not write (links, non-UTF-8, `..`, known games).
//! Python 3 is needed to generate the tree: the manifest tests are skipped (with a message) when it is missing.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::AtomicBool;

use emu_library::{
    Library, ScanOptions, TidyBlock, TidyOptions, TidyPlan, TidyReason, TidyStatus, TidyUnit,
};

// ------------------------------------------------------------------------------------------------ mini JSON
// serde_json is not a dependency of this crate (and Cargo.* is out of this task): the manifest is read by hand.

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(BTreeMap<String, Json>),
}

impl Json {
    fn parse(text: &str) -> Json {
        let mut p = Parser {
            b: text.as_bytes(),
            i: 0,
        };
        let v = p.value();
        p.ws();
        assert_eq!(p.i, p.b.len(), "trailing data in the manifest");
        v
    }

    fn get(&self, key: &str) -> &Json {
        match self {
            Json::Obj(m) => m.get(key).unwrap_or(&Json::Null),
            other => panic!("not an object: {other:?}"),
        }
    }

    fn str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }

    fn arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("not an array: {other:?}"),
        }
    }

    fn strs(&self) -> Vec<String> {
        self.arr()
            .iter()
            .map(|s| s.str().expect("string").to_owned())
            .collect()
    }
}

struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

impl Parser<'_> {
    fn ws(&mut self) {
        while self.i < self.b.len() && self.b[self.i].is_ascii_whitespace() {
            self.i += 1;
        }
    }

    fn eat(&mut self, c: u8) {
        self.ws();
        assert_eq!(
            self.b[self.i], c,
            "JSON: expected {:?} at {}",
            c as char, self.i
        );
        self.i += 1;
    }

    fn lit(&mut self, word: &str) {
        assert!(
            self.b[self.i..].starts_with(word.as_bytes()),
            "JSON at {}",
            self.i
        );
        self.i += word.len();
    }

    fn value(&mut self) -> Json {
        self.ws();
        match self.b[self.i] {
            b'{' => {
                self.i += 1;
                let mut m = BTreeMap::new();
                self.ws();
                if self.b[self.i] == b'}' {
                    self.i += 1;
                    return Json::Obj(m);
                }
                loop {
                    self.ws();
                    let k = self.string();
                    self.eat(b':');
                    m.insert(k, self.value());
                    self.ws();
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            return Json::Obj(m);
                        }
                        c => panic!("JSON: unexpected {:?}", c as char),
                    }
                }
            }
            b'[' => {
                self.i += 1;
                let mut a = Vec::new();
                self.ws();
                if self.b[self.i] == b']' {
                    self.i += 1;
                    return Json::Arr(a);
                }
                loop {
                    a.push(self.value());
                    self.ws();
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b']' => {
                            self.i += 1;
                            return Json::Arr(a);
                        }
                        c => panic!("JSON: unexpected {:?}", c as char),
                    }
                }
            }
            b'"' => Json::Str(self.string()),
            b't' => {
                self.lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.lit("null");
                Json::Null
            }
            _ => {
                let start = self.i;
                while self.i < self.b.len() && b"+-0123456789.eE".contains(&self.b[self.i]) {
                    self.i += 1;
                }
                Json::Num(
                    std::str::from_utf8(&self.b[start..self.i])
                        .unwrap()
                        .parse()
                        .expect("JSON number"),
                )
            }
        }
    }

    fn string(&mut self) -> String {
        assert_eq!(self.b[self.i], b'"');
        self.i += 1;
        let mut out = Vec::new();
        loop {
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.b[self.i];
                    self.i += 1;
                    match e {
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.b[self.i..self.i + 4]).unwrap();
                            self.i += 4;
                            let mut cp = u32::from_str_radix(hex, 16).unwrap();
                            if (0xD800..0xDC00).contains(&cp) {
                                assert_eq!(&self.b[self.i..self.i + 2], b"\\u");
                                let lo = u32::from_str_radix(
                                    std::str::from_utf8(&self.b[self.i + 2..self.i + 6]).unwrap(),
                                    16,
                                )
                                .unwrap();
                                self.i += 6;
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            }
                            let ch = char::from_u32(cp).expect("scalar value");
                            out.extend_from_slice(ch.to_string().as_bytes());
                        }
                        other => out.push(other),
                    }
                }
                c => out.push(c),
            }
        }
        String::from_utf8(out).expect("UTF-8 manifest")
    }
}

// ------------------------------------------------------------------------------------------------ helpers

fn python3_available() -> bool {
    Command::new("python3")
        .args(["-I", "-c", "pass"])
        .output()
        .is_ok_and(|o| o.status.success())
}

fn mktidy() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/tools/mktidy.py")
}

/// Generated tree + manifest in a temporary folder; `None` (with a message) when python3 is missing.
struct Generated {
    _tmp: tempfile::TempDir,
    out: PathBuf,
    roms: PathBuf,
    manifest: Json,
}

fn generate() -> Option<Generated> {
    if !python3_available() {
        eprintln!("python3 not found: tidy manifest test skipped");
        return None;
    }
    let tmp = tempfile::tempdir().unwrap();
    let out = tmp.path().join("gen");
    let status = Command::new("python3")
        .arg("-I")
        .arg(mktidy())
        .arg(&out)
        .status()
        .expect("python3 runs");
    assert!(status.success(), "mktidy.py failed");
    let text = fs::read_to_string(out.join("manifest.json")).unwrap();
    Some(Generated {
        roms: out.join("roms"),
        manifest: Json::parse(&text),
        out,
        _tmp: tmp,
    })
}

fn never() -> AtomicBool {
    AtomicBool::new(false)
}

fn plan_of(library: &Library, roms: &Path, firmware: &[&str]) -> TidyPlan {
    let options = TidyOptions::new(roms, &roms.with_file_name("rangement"))
        .unwrap()
        .with_firmware_names(firmware.iter().copied());
    library.plan_tidy(&options, &never(), &mut |_| {}).unwrap()
}

/// Every path under `root` with kind, size and mtime (nanoseconds); links are not followed.
fn snapshot(root: &Path) -> BTreeMap<String, String> {
    fn walk(dir: &Path, root: &Path, out: &mut BTreeMap<String, String>) {
        for e in fs::read_dir(dir).unwrap() {
            let e = e.unwrap();
            let path = e.path();
            let meta = fs::symlink_metadata(&path).unwrap();
            let mtime = meta
                .modified()
                .unwrap()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0);
            let kind = if meta.is_dir() {
                "dir"
            } else if meta.is_symlink() {
                "link"
            } else {
                "file"
            };
            let rel = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .into_owned();
            let target = if meta.is_symlink() {
                format!("->{}", fs::read_link(&path).unwrap().display())
            } else {
                String::new()
            };
            out.insert(rel, format!("{kind} {} {mtime}{target}", meta.len()));
            if meta.is_dir() {
                walk(&path, root, out);
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(root, root, &mut out);
    out
}

/// `Sure`, `Blocked`... and the reason name (`Header`, `Conflict`...); `None` for Ambiguous / Unknown.
fn status_names(status: &TidyStatus) -> (&'static str, Option<String>) {
    let ident = |d: String| {
        d.chars()
            .take_while(|c| c.is_alphanumeric() || *c == '_')
            .collect::<String>()
    };
    match status {
        TidyStatus::Sure(r) => ("Sure", Some(ident(format!("{r:?}")))),
        TidyStatus::Suggested(r) => ("Suggested", Some(ident(format!("{r:?}")))),
        TidyStatus::Ambiguous => ("Ambiguous", None),
        TidyStatus::Unknown => ("Unknown", None),
        TidyStatus::Blocked(b) => ("Blocked", Some(ident(format!("{b:?}")))),
    }
}

fn slash(p: &Path) -> String {
    p.components()
        .map(|c| c.as_os_str().to_string_lossy().into_owned())
        .collect::<Vec<_>>()
        .join("/")
}

/// What identifies a unit on both sides: its folder when moved whole, its first source, else its title.
fn plan_key(u: &TidyUnit) -> String {
    if let Some(w) = &u.whole_dir {
        slash(&w.from) + "/"
    } else if let Some(from) = u.moves.iter().map(|m| slash(&m.from)).min() {
        from
    } else {
        format!("title:{}", u.title)
    }
}

fn manifest_key(u: &Json) -> String {
    let whole = u.get("whole_dir");
    if *whole != Json::Null {
        return whole.get("from").str().unwrap().to_owned() + "/";
    }
    match u
        .get("moves")
        .arr()
        .iter()
        .map(|m| m.get("from").str().unwrap())
        .min()
    {
        Some(from) => from.to_owned(),
        None => format!("title:{}", u.get("title").str().unwrap()),
    }
}

fn plan_destination(u: &TidyUnit) -> Option<String> {
    if let Some(w) = &u.whole_dir {
        Some(slash(&w.to) + "/")
    } else if u.moves.len() == 1 {
        Some(slash(&u.moves[0].to))
    } else {
        u.moves.first().map(|m| slash(m.to.parent().unwrap()) + "/")
    }
}

// ------------------------------------------------------------------------------------------------ manifest

#[test]
fn plan_matches_the_manifest_unit_by_unit() {
    let Some(g) = generate() else { return };
    let library = Library::open_in_memory().unwrap();
    let before = snapshot(&g.out);
    let firmware: Vec<String> = g.manifest.get("firmware_names").strs_or_empty();
    let firmware: Vec<&str> = firmware.iter().map(String::as_str).collect();
    let plan = plan_of(&library, &g.roms, &firmware);
    let after = snapshot(&g.out);
    assert_eq!(before, after, "plan_tidy wrote on disk");
    assert!(!g.out.join("rangement").exists(), "no journal folder");

    let symlink = *g.manifest.get("platform").get("symlink") == Json::Bool(true);
    let mut problems = Vec::new();
    let mut expected: BTreeMap<String, &Json> = BTreeMap::new();
    for u in g.manifest.get("units").arr() {
        if !symlink && u.get("requires").str() == Some("unix") {
            continue;
        }
        let prev = expected.insert(manifest_key(u), u);
        assert!(
            prev.is_none(),
            "two manifest units share the key {}",
            manifest_key(u)
        );
    }
    let mut seen = BTreeSet::new();
    for u in &plan.units {
        let key = plan_key(u);
        assert!(
            seen.insert(key.clone()),
            "two plan units share the key {key}"
        );
        let Some(m) = expected.get(&key) else {
            problems.push(format!(
                "unexpected unit {key}: {:?} {:?}",
                u.status, u.title
            ));
            continue;
        };
        let id = m.get("id").str().unwrap();
        let (status, reason) = status_names(&u.status);
        let want_status = m.get("status").str().unwrap();
        let want_reason = m.get("reason").str().map(str::to_owned);
        if (status, &reason) != (want_status, &want_reason) {
            problems.push(format!(
                "{id}: status {status}/{reason:?}, manifest {want_status}/{want_reason:?}"
            ));
        }
        if u.system.as_deref() != m.get("system").str() {
            problems.push(format!(
                "{id}: system {:?}, manifest {:?}",
                u.system,
                m.get("system").str()
            ));
        }
        if u.candidates != m.get("candidates").strs() {
            problems.push(format!(
                "{id}: candidates {:?}, manifest {:?}",
                u.candidates,
                m.get("candidates").strs()
            ));
        }
        let moves: BTreeSet<(String, String)> = u
            .moves
            .iter()
            .map(|x| (slash(&x.from), slash(&x.to)))
            .collect();
        let want_moves: BTreeSet<(String, String)> = m
            .get("moves")
            .arr()
            .iter()
            .map(|x| {
                (
                    x.get("from").str().unwrap().into(),
                    x.get("to").str().unwrap().into(),
                )
            })
            .collect();
        if moves != want_moves {
            problems.push(format!("{id}: moves {moves:?}, manifest {want_moves:?}"));
        }
        let whole = u.whole_dir.as_ref().map(|w| (slash(&w.from), slash(&w.to)));
        let want_whole = match m.get("whole_dir") {
            Json::Null => None,
            w => Some((
                w.get("from").str().unwrap().to_owned(),
                w.get("to").str().unwrap().to_owned(),
            )),
        };
        if whole != want_whole {
            problems.push(format!(
                "{id}: whole_dir {whole:?}, manifest {want_whole:?}"
            ));
        }
        if plan_destination(u).as_deref() != m.get("destination").str() {
            problems.push(format!(
                "{id}: destination {:?}, manifest {:?}",
                plan_destination(u),
                m.get("destination").str()
            ));
        }
    }
    for (key, m) in &expected {
        if !seen.contains(key) {
            problems.push(format!(
                "{}: unit missing from the plan ({key})",
                m.get("id").str().unwrap()
            ));
        }
    }
    if plan.units.len() != expected.len() {
        problems.push(format!(
            "unit count {}, manifest {}",
            plan.units.len(),
            expected.len()
        ));
    }

    // Everything under a first-level roms/<id>/ is already tidy and never analysed.
    let tidy_dirs: BTreeSet<&str> = g
        .manifest
        .get("ignored")
        .arr()
        .iter()
        .filter(|i| i.get("reason").str() == Some("already_sorted"))
        .map(|i| i.get("path").str().unwrap())
        .collect();
    assert_eq!(plan.already_tidy, tidy_dirs.len() as u64, "already_tidy");
    let listed: BTreeSet<String> = plan.ignored_paths.iter().map(|p| slash(p)).collect();
    for i in g.manifest.get("ignored").arr() {
        let path = i.get("path").str().unwrap();
        if matches!(i.get("reason").str(), Some("firmware_name" | "not_a_game")) {
            assert!(
                listed.contains(path),
                "{path} must be listed in ignored_paths"
            );
        } else {
            assert!(!listed.contains(path), "{path} is tidy, not ignored");
        }
    }
    assert!(
        problems.is_empty(),
        "{} difference(s):\n{}",
        problems.len(),
        problems.join("\n")
    );
}

trait StrsOrEmpty {
    fn strs_or_empty(&self) -> Vec<String>;
}

impl StrsOrEmpty for Json {
    fn strs_or_empty(&self) -> Vec<String> {
        match self {
            Json::Null => Vec::new(),
            other => other.strs(),
        }
    }
}

// ------------------------------------------------------------------------------------------------ extra cases

fn write(path: &Path, data: &[u8]) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, data).unwrap();
}

fn noise(len: usize, seed: u8) -> Vec<u8> {
    (0..len)
        .map(|i| (i as u8).wrapping_mul(31) ^ seed)
        .collect()
}

fn find<'p>(plan: &'p TidyPlan, title: &str) -> &'p TidyUnit {
    plan.units
        .iter()
        .find(|u| u.title == title)
        .unwrap_or_else(|| panic!("no unit {title}: {:?}", plan.units))
}

#[cfg(unix)]
#[test]
fn a_linked_system_folder_and_non_utf8_names_are_blocked_and_nothing_is_written() {
    use std::os::unix::ffi::OsStrExt;
    let tmp = tempfile::tempdir().unwrap();
    let roms = tmp.path().join("roms");
    let elsewhere = tmp.path().join("elsewhere");
    fs::create_dir_all(&roms).unwrap();
    fs::create_dir(&elsewhere).unwrap();
    std::os::unix::fs::symlink(&elsewhere, roms.join("snes")).unwrap();
    write(&roms.join("Game.sfc"), &noise(32 * 1024, 1));
    write(
        &roms.join(std::ffi::OsStr::from_bytes(b"caf\xe9.sfc")),
        &noise(32 * 1024, 2),
    );
    let before = snapshot(tmp.path());
    let library = Library::open_in_memory().unwrap();
    let plan = plan_of(&library, &roms, &[]);
    assert_eq!(before, snapshot(tmp.path()), "plan_tidy wrote on disk");
    assert!(matches!(
        find(&plan, "Game").status,
        TidyStatus::Blocked(TidyBlock::DestinationNotPlainDir { .. })
    ));
    assert!(
        plan.units
            .iter()
            .any(|u| u.status == TidyStatus::Blocked(TidyBlock::NonUtf8Path))
    );
    assert_eq!(plan.already_tidy, 0, "a linked roms/snes is not walked");
}

#[test]
fn a_root_spelled_with_dot_dot_plans_relative_moves_only() {
    let tmp = tempfile::tempdir().unwrap();
    let roms = tmp.path().join("roms");
    write(&roms.join("Game.sfc"), &noise(32 * 1024, 3));
    fs::create_dir(tmp.path().join("other")).unwrap();
    let spelled = tmp.path().join("other").join("..").join("roms");
    let library = Library::open_in_memory().unwrap();
    let plan = plan_of(&library, &spelled, &[]);
    let unit = find(&plan, "Game");
    assert_eq!(unit.status, TidyStatus::Sure(TidyReason::Extension));
    for m in &unit.moves {
        for p in [&m.from, &m.to] {
            assert!(p.is_relative(), "{p:?}");
            assert!(!p.components().any(|c| c.as_os_str() == ".."), "{p:?}");
        }
    }
}

#[test]
fn a_cue_pointing_outside_the_root_is_blocked() {
    let tmp = tempfile::tempdir().unwrap();
    let roms = tmp.path().join("roms");
    write(
        &roms.join("Out.cue"),
        b"FILE \"../outside.bin\" BINARY\r\n  TRACK 01 MODE1/2352\r\n    INDEX 01 00:00:00\r\n",
    );
    write(&tmp.path().join("outside.bin"), &noise(2352, 4));
    let library = Library::open_in_memory().unwrap();
    let plan = plan_of(&library, &roms, &[]);
    assert!(
        matches!(
            find(&plan, "Out").status,
            TidyStatus::Blocked(TidyBlock::OutsideReference { .. })
        ),
        "{:?}",
        find(&plan, "Out").status
    );
}

#[test]
fn a_game_known_to_the_library_keeps_its_system() {
    let tmp = tempfile::tempdir().unwrap();
    let roms = tmp.path().join("roms");
    // Same extension for gb and gbc: the scan decides from the header, the plan reuses its answer.
    let mut data = noise(32 * 1024, 5);
    data[0x143] = 0x00;
    write(&roms.join("Known.gb"), &data);
    let mut library = Library::open_in_memory().unwrap();
    library
        .scan(
            &ScanOptions {
                roots: vec![roms.clone()],
                ..Default::default()
            },
            &never(),
            &mut |_| {},
        )
        .unwrap();
    let game = library
        .games()
        .unwrap()
        .into_iter()
        .next()
        .expect("one game");
    let plan = plan_of(&library, &roms, &[]);
    let unit = find(&plan, "Known");
    assert!(unit.known_game.is_some());
    assert_eq!(unit.system.as_deref(), Some(game.system.as_str()));
    assert_eq!(unit.status, TidyStatus::Sure(TidyReason::Library));
    assert_eq!(unit.system_change, None);
}

#[test]
fn group_and_playlist_titles_lose_only_their_own_markers() {
    let tmp = tempfile::tempdir().unwrap();
    let roms = tmp.path().join("roms");
    write(&roms.join("MANIACD0.D64"), &noise(2048, 1));
    write(&roms.join("MANIACD1.D64"), &noise(2048, 2));
    write(&roms.join("t1.d64"), &noise(2048, 3));
    write(&roms.join("t2.d64"), &noise(2048, 4));
    write(&roms.join("Tekken 3.m3u"), b"t1.d64\nt2.d64\n");
    let mut library = Library::open_in_memory().unwrap();
    library
        .scan(
            &ScanOptions {
                roots: vec![roms.clone()],
                ..Default::default()
            },
            &never(),
            &mut |_| {},
        )
        .unwrap();
    let plan = plan_of(&library, &roms, &[]);
    find(&plan, "MANIACD");
    find(&plan, "Tekken 3");
}
